import React, { useEffect, useState } from "react";
import Nav from './component/nav';
import api from '../api';
import Header from "./component/header";

const Pendaftar = () => {
  const [data, setData] = useState([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [formData, setFormData] = useState({
    customHari: "",
    hari: "",
    waktu: "",
  });
  const [message, setMessage] = useState("");

  const handleChange = (e) => {
    const { id, value } = e.target;
    setFormData({ ...formData, [id]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const hariValue = formData.hari === "custom" ? formData.customHari : formData.hari;
      const response = await api.post("/presensi/create", {
        hari: hariValue,
        waktu: parseInt(formData.waktu),
      });
      const mahasiswaData = response.data.absen.map(item => item.mahasiswa);
      setData(mahasiswaData)

      setMessage(response.data.message);
    } catch (error) {
      console.error(error);
      setMessage("Gagal membuka presensi.");
    }
  };
  const handleCustomChange = (e) => {
    setFormData({
      ...formData,
      customHari: e.target.value,
    });
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  return (
    <div className="flex flex-col h-screen bg-teal-100 font-sans">
      {/* Header */}
      <Header  isSidebarOpen={isSidebarOpen} setIsSidebarOpen={setIsSidebarOpen}/>

      {/* Container */}
      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <Nav isSidebarOpen={isSidebarOpen} />

        {/* Main Content */}
        <main className="flex-1 bg-teal-50 p-6 overflow-y-auto">
          <h2 className="text-4xl font-bold mb-4">Presensi</h2>
          <div className="overflow-x-auto">
            <form onSubmit={handleSubmit}>
              <div className="mb-4">
                <label htmlFor="hari" className="block text-teal-800 font-medium mb-2">hari Terbuka (Menit)</label>
                <select
                  id="hari"
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  value={formData.hari}
                  onChange={handleChange}
                  required
                >
                  <option value="" disabled>Pilih hari pertemua</option>
                  <option value="hari ke-1">Hari ke-1</option>
                  <option value="hari ke-2">Hari ke-2</option>
                  <option value="hari ke-3">Hari ke-3</option>
                  <option value="hari ke-4">Hari ke-4</option>
                  <option value="hari ke-5">Hari ke-5</option>
                  <option value={`${formData.customHari}`}>Tambah Pertemuan</option>
                </select>
                {formData.hari === "" && (
                  <input
                    id="hari"
                    type="text"
                    value={formData.customHari}
                    onChange={handleCustomChange}
                    placeholder="Masukkan hari lain"
                    className="mt-2 w-full p-3 border border-teal-300 rounded-lg"
                  />
                )}
              </div>

              <div className="mb-4">
                <label htmlFor="waktu" className="block text-teal-800 font-medium mb-2">Waktu Terbuka (Menit)</label>
                <select
                  id="waktu"
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  value={formData.waktu}
                  onChange={handleChange}
                >
                  <option value="" disabled>Pilih waktu selesai</option>
                  <option value="5">5 menit</option>
                  <option value="10">10 menit</option>
                  <option value="15">15 menit</option>
                </select>
              </div>

              <button type="submit" className="w-full py-3 bg-teal-500 text-white rounded-lg hover:bg-teal-600">
                Buat Presensi
              </button>
            </form>
          </div>
          <table className="mt-4 min-w-full bg-white border border-teal-300 rounded-lg shadow">
              <thead className="bg-teal-700 text-white">
                <tr>
                  <th className="px-6 py-3 text-left font-medium">NIM</th>
                  <th className="px-6 py-3 text-left font-medium">Nama</th>
                  <th className="px-6 py-3 text-left font-medium">Aksi</th>
                </tr>
              </thead>
              <tbody>
              {data.length > 0 ? (
                data.map((row) => (
                  <tr key={row.id}>
                    <td className="px-6 py-4">{row.nim}</td>
                    <td className="px-6 py-4">{row.nama}</td>
                    {/* <td className="px-6 py-4">{row.alamat}</td> */}

                  </tr>
                ))) : (
                  <tr>
                    <td
                      colSpan="3"
                      className="text-center px-6 py-4 text-gray-500"
                    >
                      Tidak ada jadwal tersedia.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
        </main>
      </div>
    </div>
  );
};

export default Pendaftar;
